Consider something like this which has less lookups, consumes less ram and can fail early.

```
def is_manifold(geometry: W.Triangulation) -> bool:
    """Check whether the triangulation is closed and consistently oriented."""
    faces = geometry.faces
    edge_state: dict[tuple[int, int], int] = {}

    for i in range(0, len(faces), 3):
        a = faces[i]
        b = faces[i + 1]
        c = faces[i + 2]

        for u, v in ((a, b), (b, c), (c, a)):
            if u == v:
                return False

            if u < v:
                edge = (u, v)
                direction = 1
            else:
                edge = (v, u)
                direction = -1

            state = edge_state.get(edge)

            if state is None:
                # First use: remember its orientation.
                edge_state[edge] = direction
            elif state == -direction:
                # Second use in the opposite direction: edge is complete.
                edge_state[edge] = 0
            else:
                # Same orientation twice, or any third use.
                return False

    # Non-zero entries are boundary edges used only once.
    return all(state == 0 for state in edge_state.values())
```

